-- Seed file: English translations for makgeolli
-- Generated from output_en.csv (432 rows)
-- Applies to makgeolli_translations with locale='en'

BEGIN;

-- Upsert for idempotency: re-running updates existing locale='en' rows
ON CONFLICT (makgeolli_id, locale) DO UPDATE SET
  name        = EXCLUDED.name,
  brewery     = EXCLUDED.brewery,
  awards      = EXCLUDED.awards,
  ingredients = EXCLUDED.ingredients,
  description = EXCLUDED.description,
  updated_at  = now();

COMMIT;
